// Build the AI prompt with all author & book data
const author = $('HTTP - Fetch Author from Bubble').first().json.response;
const books = $('HTTP - Fetch Author Books from Bubble').first().json.response.results;
const webhookData = $('Webhook - Receive Trigger').first().json.body;

// Calculate consolidated figures
let totalEarned = 0;
let totalPaid = 0;
let totalPending = 0;
let publishedBooks = [];
let productionBooks = [];

for (const book of books) {
  totalEarned += book.total_royalty_earned || 0;
  totalPaid += book.royalty_paid || 0;
  totalPending += book.royalty_pending || 0;

  if (book.status && book.status.includes('Published')) {
    publishedBooks.push(book);
  } else {
    productionBooks.push(book);
  }
}

// Build book details string for the prompt
let bookDetails = '';
for (const book of publishedBooks) {
  bookDetails += `\n- "${book.title}" (${book.genre})\n`;
  bookDetails += `  Status: ${book.status}\n`;
  bookDetails += `  Copies Sold: ${book.total_copies_sold}\n`;
  bookDetails += `  Total Royalty Earned: ₹${book.total_royalty_earned?.toLocaleString('en-IN')}\n`;
  bookDetails += `  Royalty Paid: ₹${book.royalty_paid?.toLocaleString('en-IN')}\n`;
  bookDetails += `  Royalty Pending: ₹${book.royalty_pending?.toLocaleString('en-IN')}\n`;
  bookDetails += `  Last Payout Date: ${book.last_royalty_payout_date || 'No payout yet'}\n`;
}

for (const book of productionBooks) {
  bookDetails += `\n- "${book.title}" (${book.genre})\n`;
  bookDetails += `  Status: ${book.status} (In Production — not yet published)\n`;
}

const prompt = `You are a customer communications specialist for BookLeaf Publishing. Generate a professional, warm royalty summary email for an author.

BOOKLEAF KNOWLEDGE BASE:
BookLeaf Publishing is a self-publishing company operating in India and the US.
ROYALTY POLICY:
- 80/20 split: 80% of net profit to author, 20% to BookLeaf.
- Net profit = MRP minus printing cost, platform commission (Amazon/Flipkart), and shipping charges.
- Royalties calculated quarterly, paid within 45 days of quarter end.
- Quarterly cycle: Q1 (Jan-Mar) paid by mid-May, Q2 (Apr-Jun) paid by mid-Aug, Q3 (Jul-Sep) paid by mid-Nov, Q4 (Oct-Dec) paid by mid-Feb.
- Minimum payout threshold: ₹1,000. Below this, rolls over to next quarter.
- Payouts via bank transfer to linked account.

TONE GUIDELINES:
- Always empathetic and professional. Authors are partners, not customers.
- Acknowledge concern before solutions.
- Be specific with numbers, dates, statuses — no vague reassurances.
- If BookLeaf's fault, own it directly. No corporate deflection.
- Always end with clear next step.

AUTHOR DATA:
- Name: ${author.name}
- Email: ${author.email}

BOOKS:
${bookDetails}

CONSOLIDATED SUMMARY:
- Total Earned across all books: ₹${totalEarned.toLocaleString('en-IN')}
- Total Paid: ₹${totalPaid.toLocaleString('en-IN')}
- Total Pending: ₹${totalPending.toLocaleString('en-IN')}

INSTRUCTIONS:
1. Open with a personalised greeting using the author's first name.
2. For each published book, provide a concise royalty summary with sales and payment figures.
3. Clearly show: total earned, total paid, total pending.
4. If there's a pending amount, explain when they can expect the next payout based on the quarterly cycle and 45-day window. Calculate the specific expected date.
5. If all royalties are fully paid, include a positive acknowledgement.
6. If any books are still in production (not yet published), give a brief status update and mention the next expected production stage.
7. Close warmly and professionally, matching BookLeaf's tone.
8. Keep the email concise but thorough (300-500 words).
9. Format with clear sections and line breaks for readability.
10. Use ₹ symbol for all Indian currency amounts.
11. Do NOT include a subject line — just the email body.
12. Sign off as "The BookLeaf Royalty Team".`;

return {
  prompt: prompt,
  author_name: author.name,
  author_email: author.email,
  author_bubble_id: webhookData.author_bubble_id,
  idempotency_key: webhookData.idempotency_key,
  callback_url: webhookData.callback_url,
  total_pending: totalPending,
  total_earned: totalEarned,
  total_paid: totalPaid
};

// Extract the generated email content from Gemini response
const aiResponse = $('HTTP - Gemini AI Generate Summary').first().json;
const previousData = $('Code - Build AI Prompt').first().json;

let emailContent = '';

try {
  emailContent = aiResponse.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Failed to extract AI response: ' + JSON.stringify(aiResponse));
}

return {
  email_content: emailContent,
  author_name: previousData.author_name,
  author_email: previousData.author_email,
  author_bubble_id: previousData.author_bubble_id,
  callback_url: previousData.callback_url,
  idempotency_key: previousData.idempotency_key,
  status: 'Success'
};

parameters.responseBody:
={
  "status": "success",
  "message": "Royalty summary generated and sent successfully",
  "author_bubble_id": "{{ $('Code - Extract Email Content').item.json.author_bubble_id }}"
}

